// ═══ HashMap: equals() ═══
Map<String, String> hashMap = new HashMap<>();
String key1 = new String("SAV2001");
String key2 = new String("SAV2001");
hashMap.put(key1, "first");
hashMap.put(key2, "second");
hashMap.size();  // 1! key1.equals(key2) → same key → value replaced!

// ═══ IdentityHashMap: == ═══
Map<String, String> idMap = new IdentityHashMap<>();
idMap.put(key1, "first");
idMap.put(key2, "second");
idMap.size();  // 2! key1 != key2 (different objects) → TWO keys!

// String literals are interned → same reference:
idMap.put("SAV2001", "a");
idMap.put("SAV2001", "b");
idMap.size();  // still 2 + 1 = now key count depends on interning!
// "SAV2001" == "SAV2001" (literals are interned) → same key → replaced

// ═══ USE CASE: cycle detection in object graph traversal ═══
IdentityHashMap<Object, Boolean> visited = new IdentityHashMap<>();
// When traversing objects: have I visited THIS EXACT object before?
// Two objects with same equals() but different identity → must visit both!
if (visited.put(obj, Boolean.TRUE) != null) {
    // Already visited this EXACT object → CYCLE detected!
}

// ═══ USE CASE: serialization/deep copy ═══
// When serializing: track which EXACT objects have been serialized
// Two Employee objects with same name → DIFFERENT objects → serialize both
// IdentityHashMap<Object, Integer> objectToId → maps each unique object to an ID
