package com.bank.identity;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class IdentityHashMapTest {

    @Test
    void hashMap_usesEquals() {
        Map<String, String> map = new HashMap<>();
        map.put(new String("SAV2001"), "first");
        map.put(new String("SAV2001"), "second");
        assertThat(map).hasSize(1);  // equals() → same key!
    }

    @Test
    void identityHashMap_usesReferenceEquality() {
        Map<String, String> map = new IdentityHashMap<>();
        map.put(new String("SAV2001"), "first");
        map.put(new String("SAV2001"), "second");
        assertThat(map).hasSize(2);  // different objects → different keys!
    }

    @Test
    void stringLiterals_sameReference() {
        Map<String, String> map = new IdentityHashMap<>();
        map.put("SAV2001", "first");
        map.put("SAV2001", "second");
        assertThat(map).hasSize(1);  // literals are interned → SAME reference → replaced!
    }

    @Test
    void cycleDetection() {
        IdentityHashMap<Object, Boolean> visited = new IdentityHashMap<>();
        Object obj = new Object();
        assertThat(visited.put(obj, true)).isNull();     // first visit
        assertThat(visited.put(obj, true)).isTrue();     // CYCLE! Already visited!
    }
}
